/**
 * Create a new itinerary.
 * @param {Object} data - The itinerary data.
 * @returns {Promise<Object>} The created itinerary.
 */
export const createItinerary = async (data) => {
  console.log('%c[createItinerary] Request data:', 'color: blue;', data);
  const response = await backendApiClient.post('/itineraries/api/v1/itineraries', data);
  console.log('%c[createItinerary] Response:', 'color: green;', response);
  return response.data?.data;
};

