async function TEST_ALL(realUser = false) {
  let user;
  if (realUser) {
    console.log('USING REAL USER:');
    // Create a new itinerary
    user = usersService.getLoggedUser();
  } else {
    console.log('USING MOCK USER1:');
    user = await usersService.postLogin({ userId: "user1", password: "password1" });
  }
  const newItinerary = {
    name: 'Vacation in Hawaii',
    description: 'A relaxing vacation in Hawaii',
    startDate: new Date(),
    endDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7 days from now
    activities: [],
    comments: [],
    reviews: []
  };

  const newActivity = {
    userId: user._id,
    name: 'Snorkeling',
    description: 'Snorkeling in the coral reefs',
    startDate: new Date(Date.now() + 1 * 24 * 60 * 60 * 1000), // 1 day from now
    endDate: new Date(Date.now() + 1 * 24 * 60 * 60 * 1000 + 2 * 60 * 60 * 1000), // 2 hours duration
    location: {
      latitude: 21.3069,
      longitude: -157.8583,
      address: 'Waikiki Beach, Honolulu, HI'
    }
  };

  const createdItinerary = await createItinerary(newItinerary);
  console.log('Created Itinerary:', createdItinerary);
  // Get all itineraries
  const allItineraries = await getAllItineraries();
  console.log('All Itineraries:', allItineraries);

  // Get a specific itinerary by ID
  const itineraryId = createdItinerary._id;
  const itinerary = await getItineraryById(itineraryId);
  console.log('Itinerary by ID:', itinerary);

  // Update the itinerary
  const updatedData = { name: 'Updated Vacation in Hawaii2', ...createdItinerary };
  const updatedItinerary = await updateItineraryById(itineraryId, updatedData);
  console.log('Updated Itinerary:', updatedItinerary);

  // Add an activity to the itinerary

  const addedActivity = await addActivityToItinerary(itineraryId, newActivity);
  console.log('Added Activity:', addedActivity);

  // Get all activities for the itinerary
  const activities = await getActivitiesByItineraryId(itineraryId);
  console.log('Activities:', activities);

  // Get a specific activity by index
  const activityIndex = 0;
  const activity = await getActivityByIndex(itineraryId, activityIndex);
  console.log('Activity by Index:', activity);

  // Get the weather forecast for the activity
  const activityForecast = await getActivityForecast(itineraryId, activityIndex);
  console.log('Activity Forecast:', activityForecast);

  // Submit a comment for the itinerary
  const newComment = { title: 'This looks amazing!', message: 'This looks amazing!' };
  const addedComment = await submitCommentForItinerary(itineraryId, newComment);
  console.log('Added Comment:', addedComment);

  // Get all comments for the itinerary
  const comments = await getCommentsByItineraryId(itineraryId);
  console.log('Comments:', comments);

  // Submit a review for the itinerary
  const newReview = { score: 5, title: 'Best vacation ever!', message: 'Best vacation ever!' };
  const addedReview = await submitReviewForItinerary(itineraryId, newReview);
  console.log('Added Review:', addedReview);

  // Get all reviews for the itinerary
  const reviews = await getReviewsByItineraryId(itineraryId);
  console.log('Reviews:', reviews);

  // Get the average review score for the itinerary
  const averageReviewScore = await getAverageReviewScoreByItineraryId(itineraryId);
  console.log('Average Review Score:', averageReviewScore);

  // Delete the itinerary
  await deleteItineraryById(itineraryId);
  console.log('Itinerary deleted successfully');
};